(()=>{'use strict';const form=document.getElementById('form-login-gate');if(!form)return;
const style=document.createElement('style');style.textContent='#tela-login-gate{overflow-y:auto;align-items:flex-start;padding:20px 12px}#tela-login-gate>div{margin:auto}#primeiro-acesso-local label{display:block;margin:10px 0}#primeiro-acesso-local input{box-sizing:border-box;max-width:100%}';document.head.append(style);const box=document.createElement('section');box.id='primeiro-acesso-local';box.style.cssText='padding:14px;border:1px solid #d97706;border-radius:10px;color:#e2e8f0;margin-top:16px';box.innerHTML='<h3>Primeiro acesso neste navegador</h3><p>Defina sua senha para o usuário demonstrativo teste. Não há senha padrão. Este acesso é local e não autentica no Supabase. Use somente dados fictícios.</p><label>Senha local (12 a 128 caracteres)<input id="setup-local-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" style="width:100%;color:#0f172a;padding:10px"></label><label>Confirme a senha<input id="setup-local-confirm" type="password" autocomplete="new-password" maxlength="128" style="width:100%;color:#0f172a;padding:10px"></label><button id="setup-local-save" type="button" style="padding:10px;background:#f59e0b;color:#0f172a">Definir senha local</button><p id="setup-local-status" role="status"></p>';form.after(box);
function refresh(){try{box.hidden=!MartinsAcessoLocal.pending(getUsuariosDb());}catch{box.hidden=true;}}
document.getElementById('setup-local-save').onclick=()=>{const password=document.getElementById('setup-local-password'),confirmation=document.getElementById('setup-local-confirm'),status=document.getElementById('setup-local-status');try{const key='cm_usuarios_db',before=localStorage.getItem(key),users=getUsuariosDb();if(localStorage.getItem(key)!==before)throw Error('Cadastros alterados; recarregue antes de definir a senha');const next=MartinsAcessoLocal.setup(users,password.value,confirmation.value);MartinsJornada.write(localStorage,key,next,before);password.value='';confirmation.value='';document.getElementById('gate-usuario-input').value='teste';refresh();showToast('Senha local definida. Entre com o usuário teste e a senha escolhida.');}catch(e){status.textContent=e.message;}};
window.addEventListener('storage',refresh);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',refresh);refresh();
})();
